// TODO(qr): node-qrcode ("qrcode" on npm) is NOT bundled with n8n. Either:
//   1) docker exec posfinal-n8n npm install qrcode
//      and set NODE_FUNCTION_ALLOW_EXTERNAL=qrcode, or
//   2) replace this node with an HTTP Request to a QR generation service.
let qrDataUrl = '';
let publicUrl = '';
try {
  const QRCode = require('qrcode');
  const base = String($env.NEXT_PUBLIC_BASE_URL || 'https://amor.uniongloss.com');
  const trimmed = base.charAt(base.length - 1) === '/' ? base.slice(0, -1) : base;
  const slug = $json.slug || '';
  publicUrl = trimmed + '/s/' + slug;
  qrDataUrl = await QRCode.toDataURL(publicUrl, { errorCorrectionLevel: 'H', margin: 4, width: 1024 });
} catch (error) {
  throw new Error('QR generation unavailable: ' + error.message + ' (install qrcode, see TODO)');
}
return [{ json: { publicUrl: publicUrl, qrDataUrl: qrDataUrl, qrBase64: qrDataUrl.split(',')[1] || '' } }];

const crypto = require('crypto');

function safeEqual(a, b) {
  const left = Buffer.from(String(a));
  const right = Buffer.from(String(b));
  if (left.length !== right.length) return false;
  return crypto.timingSafeEqual(left, right);
}

const item = $input.first();
const json = item.json || {};
const headers = json.headers || {};
const provided = headers['x-latido-secret'] || '';
const expected = $env.LATIDO_ADMIN_SECRET || '';
const authorized = expected.length > 0 && safeEqual(provided, expected);

// TODO(latido): constant-time shared-secret check. Replace with the native
// signature scheme once confirmed against the provider docs.
return [{ json: Object.assign({}, json, { authorized }) }];
